 {pathname==='/inventario'&&<><div className="intro-row inventory-intro"><div className="network-stat"><div><div className="stat-number">{activeProperties.length.toString().padStart(2,'0')}</div><div className="stat-caption">Propiedades vigentes</div></div><div className="stat-divider"/><div><div className="stat-number">{new Set(activeProperties.map(p=>p.owner)).size.toString().padStart(2,'0')}</div><div className="stat-caption">Asesores con inventario</div></div><div className="stat-divider"/><div><div className="stat-number">{requirements.filter(r=>r.status==='Activo').length.toString().padStart(2,'0')}</div><div className="stat-caption">{guest?'Solicitudes de ejemplo':'Mis solicitudes'}</div></div></div></div><div className="search-panel"><div className="search-input"><Search size={18}/><input aria-label="Buscar por características, zona o asesor" maxLength={500} value={q} onChange={e=>setQ(e.target.value)} placeholder="Ej. casa con jardín en El Molino"/></div><Pick value={operation} onChange={setOperation} items={['Todas las operaciones','Venta','Renta']} label="Operación"/><Pick value={type} onChange={setType} items={['Todos los tipos',...propertyTypes]} label="Tipo de propiedad"/><LocationSearch value={zone} onChange={setZone} suggestions={properties.flatMap(p=>[p.zone,p.clientDetails?.neighborhood||'',p.clientDetails?.postalCode||'',p.clientDetails?.address||''])}/><button className="btn secondary" onClick={()=>setDialog('filters')}><SlidersHorizontal size={16}/>Filtros{(maxPrice||minBeds!=='0'||garden)?' · activos':''}</button></div><div className="search-understanding"><div><span className="eyebrow">Criterios de tu búsqueda</span><CriteriaChips labels={criteriaLabels(effectiveSearch)}/>{!q&&<p>{guest?'Prueba una búsqueda o aplica filtros. Para guardar solicitudes y recibir alertas, necesitas acceso.':'Escribe qué busca tu cliente o aplica filtros. Después, guarda la búsqueda para recibir alertas de nuevas opciones.'}</p>}</div><button className="btn secondary small" disabled={guest||loading||saving||!!error} title={guest?'Necesitas acceso para guardar una búsqueda':undefined} onClick={()=>openRequirementForm(null,true)}><Plus size={15}/>Guardar esta búsqueda</button></div><div className="results-header"><Tabs value={savedTab} onValueChange={setSavedTab}><TabsList variant="line"><TabsTrigger value="all">Todo el inventario</TabsTrigger><TabsTrigger value="saved" disabled={guest}><Bookmark size={14}/>Guardadas {saved.length>0&&`(${saved.length})`}</TabsTrigger></TabsList></Tabs><div className="row"><span className="results-caption">{filtered.length} propiedades</span><Pick value={order} onChange={setOrder} items={['Más recientes','Menor precio','Mayor precio']} label="Ordenar propiedades"/></div></div>{hasFilters&&<div className="row" style={{marginBottom:'1rem'}}><span className="meta">Filtros aplicados</span><button className="reset-filters" onClick={resetFilters}>Limpiar filtros</button></div>}{filtered.length?<div className="property-grid">{filtered.map(p=><PropertyCard key={p.id} p={p} open={setSelected}/>)}</div>:<Blank title={savedTab==='saved'?'No hay propiedades guardadas con estos filtros':'No encontramos opciones con estos filtros'} description="Guarda esta búsqueda como solicitud. Quedará en espera y te avisaremos cuando aparezca una posible coincidencia."/>}<div className="grid-footer"><span className="row"><ShieldCheck size={14}/>Disponibilidad declarada por el responsable. Las fichas iniciales usan fotos de referencia.</span><a href="https://www.pexels.com/@heyho/" target="_blank" rel="noreferrer">Fotos iniciales: Max Vakhtbovych / Pexels</a></div></>}
