 {pathname==='/colaboraciones'&&<><Tabs value={collabTab} onValueChange={setCollabTab}><TabsList variant="line"><TabsTrigger value="Recibida">Recibidas ({collaborations.filter(c=>c.direction==='Recibida').length})</TabsTrigger><TabsTrigger value="Enviada">Enviadas ({collaborations.filter(c=>c.direction==='Enviada').length})</TabsTrigger></TabsList></Tabs><div className="spacer"/><div className="split-layout"><div className="collab-list">{visibleCollab.length?visibleCollab.map(c=>{const p=properties.find(x=>x.id===c.propertyId);if(!p)return null;return <article className="panel collab-card" key={c.id}><img className="collab-photo" src={p.image} alt="Fotografía de referencia"/><div><div className="row between"><span className="eyebrow">{c.id}</span><span className={'tag'+(c.status==='Pendiente'?' amber':c.status==='Rechazada'?' red':c.status==='Aclaración'?' blue':'')}>{c.status}</span></div><h3 style={{marginTop:'.7rem'}}>{p.title}</h3><p>{c.direction==='Recibida'?'De':'Para'} {c.colleague} · {c.requirementId||'Sin solicitud de búsqueda vinculada'}</p><p>“{c.message}”</p><div className="conditions-snapshot"><strong>{money(c.priceSnapshot)} MXN · {commissionText(c.operationSnapshot,c.commissionSnapshot)}</strong><div style={{marginTop:'.3rem'}}>{c.status==='Aceptada'?`Condiciones aceptadas · ${c.acceptedAt}`:'Condiciones registradas al solicitar'} · {c.conditionsSnapshot}</div></div><div className="collab-timeline">{c.events?.map((event,i)=><div key={i}><span className="avatar">{profile(event.actorId,networkProfiles).initials}</span><p><strong>{profile(event.actorId,networkProfiles).name.split(' ')[0]}</strong> · {event.text}<small>{new Date(event.at).toLocaleString('es-MX',{dateStyle:'short',timeStyle:'short'})}</small></p></div>)}</div><div className="collab-actions">{!guest&&c.direction==='Recibida'&&c.status==='Pendiente'&&<><button className="btn small" onClick={()=>updateCollaboration(c,'Aceptada')}><Check size={14}/>Aceptar condiciones</button><button className="btn secondary small" onClick={()=>{setActiveCollab(c);setDialog('clarify')}}>Pedir aclaración</button><button className="btn secondary small" onClick={()=>updateCollaboration(c,'Rechazada')}>Rechazar</button></>}{!guest&&c.direction==='Enviada'&&c.status==='Aclaración'&&<button className="btn small" onClick={()=>{setActiveCollab(c);setReport(false);setDialog('clarify')}}>Responder aclaración</button>}{!guest&&c.status==='Aceptada'&&<button className="btn small" onClick={()=>{setSelected(p);setActiveCollab(c);setDialog('contact')}}><UserRound size={14}/>Ver contacto</button>}<button className="btn secondary small" onClick={()=>setSelected(p)}>Ver propiedad</button>{member.role==='admin'&&<button className="other-profile-link" disabled={saving} onClick={()=>{switchProfile((c.direction==='Enviada'?c.recipientId:c.senderId) as ActorId);setSelected(null);setDialog(null);setCollabTab(c.direction==='Enviada'?'Recibida':'Enviada');navigate('/colaboraciones')}}>Ver como {c.colleague.split(' ')[0]}</button>}</div></div></article>}):<Blank title="Sin solicitudes en esta pestaña" description="Abre una propiedad compatible y registra una solicitud de prueba."/>}</div><aside className="panel" style={{alignSelf:'start'}}><h2>Un acuerdo claro</h2><div className="steps">{[['Solicitar','El inmueble, el requerimiento y las condiciones quedan vinculados.'],['Confirmar','La contraparte acepta, rechaza o pide una aclaración.'],['Coordinar','Al aceptar se muestran los datos de contacto de la contraparte.']].map(([a,b],i)=><div className="step" key={a}><span className="step-num">{i+1}</span><div><strong>{a}</strong><p>{b}</p></div></div>)}</div><p className="help-strip"><Info size={17}/>Una solicitud aceptada no se cuenta como visita ni cierre.</p></aside></div></>}
 {pathname==='/mis-propiedades'&&<><div className="requirement-callout" style={{marginBottom:'1.5rem'}}><div className="row"><RefreshCw size={20}/><div><h3>{properties.filter(p=>p.mine&&p.status==='Pendiente de reconfirmación').length} publicación pendiente de reconfirmación</h3><p>Solo las propiedades disponibles aparecen en las búsquedas de la red.</p></div></div><span className="tag gray">Vigencia de ejemplo</span></div><div className="panel">{properties.filter(p=>p.mine).map(p=><div key={p.id} className="own-row"><img src={p.image} alt="Fotografía de la propiedad"/><div className="own-info"><h3>{p.title}</h3><p>{p.id} · {p.zone} · {money(p.price)}</p><p>Última confirmación: {p.confirmed.toLowerCase()}</p></div><div className="own-actions"><Select value={p.status} onValueChange={async v=>{if(await setProperties(old=>old.map(x=>x.id===p.id?{...x,status:v as PropertyStatus,confirmed:v==='Disponible'?'Hoy':x.confirmed}:x)))toast('Disponibilidad actualizada')}}><SelectTrigger className="filter-select" aria-label={'Estado de '+p.title}><SelectValue/></SelectTrigger><SelectContent>{['Disponible','Reservado','Vendido','Rentado','Retirado','Pendiente de reconfirmación'].filter(s=>!(s==='Vendido'&&p.operation==='Renta')&&!(s==='Rentado'&&p.operation==='Venta')).map(s=><SelectItem key={s} value={s}>{s}</SelectItem>)}</SelectContent></Select><button className="btn secondary small" onClick={async()=>{if(await setProperties(old=>old.map(x=>x.id===p.id?{...x,status:'Disponible',confirmed:'Hoy'}:x)))toast.success('Disponibilidad reconfirmada')}}><RefreshCw size={14}/>Reconfirmar</button><button className="btn secondary small" onClick={()=>openPropertyForm(p)}>Editar</button></div></div>)}</div><div className="help-strip"><Clock3 size={18}/>Una ficha pendiente de reconfirmación se oculta del inventario. Reconfirmarla la vuelve a mostrar; retirarla conserva el registro. La duración real de vigencia está por definir.</div></>}
